CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS profissionais (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL, ativo boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS servicos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nome text NOT NULL, preco_centavos integer NOT NULL CHECK (preco_centavos >= 0), duracao_min integer NOT NULL CHECK (duracao_min > 0), buffer_antes_min integer NOT NULL DEFAULT 0, buffer_depois_min integer NOT NULL DEFAULT 0, ativo boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS profissional_servico (profissional_id uuid REFERENCES profissionais(id), servico_id uuid REFERENCES servicos(id), PRIMARY KEY (profissional_id, servico_id));
CREATE TABLE IF NOT EXISTS clientes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), telefone_e164 text UNIQUE NOT NULL, nome text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reservas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), cliente_id uuid NOT NULL REFERENCES clientes(id), profissional_id uuid NOT NULL REFERENCES profissionais(id), servico_id uuid NOT NULL REFERENCES servicos(id), inicio timestamptz NOT NULL, fim timestamptz NOT NULL, range_bloqueado tstzrange GENERATED ALWAYS AS (tstzrange(inicio - make_interval(mins => 0), fim + make_interval(mins => 0), '[)')) STORED, status text NOT NULL CHECK (status IN ('hold','confirmada','cancelada','concluida','nao_compareceu')), hold_expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK (fim > inicio));
ALTER TABLE reservas DROP CONSTRAINT IF EXISTS reservas_sem_colisao;
ALTER TABLE reservas ADD CONSTRAINT reservas_sem_colisao EXCLUDE USING gist (profissional_id WITH =, range_bloqueado WITH &&) WHERE (status IN ('hold','confirmada'));
